\caption{Tab. 9.1 – Notfallausrüstung am Feuerplatz (Prüfplan)} \\
\toprule
Ausrüstung & Menge & Prüfung \\
\midrule
\endfirsthead
\multicolumn{3}{l}{Tab. 9.1 – Fortsetzung} \\
\toprule
