\section*{Monats-Detailanleitungen (je fünf bis acht Schritte)}

\subsection*{Monat 1: Fundholz-Sortierung (Stadt) und Stapel-Datierung (Land)}
\begin{enumerate}
\item Lege drei Planen aus: „sicher", „unklar", „verboten" (Tab. 1.4).
\item Prüfe jedes Fundstück einzeln: Farbe, Stempel, Geruch, Gewicht.
\item Verbrenne nichts in diesem Monat; sortiere nur.
\item Beschrifte jeden Stapel mit Datum und Fundort.
\item Plane für den Folgemonat die Probebrände des Stapels „unklar".
\end{enumerate}

\subsection*{Monat 2: Zündset und Feuerstahl}
\begin{enumerate}
\item Baue das Zündset nach Konzept 3.2.
\item Übe fünf Zündungen in einer Schale auf Blechwanne.
\notiere Versuche und Zunderverbrauch in Vorlage A.3.
\item Übe einmal bei Wind und einmal bei Kälte.
\item Erste monatliche Prüfung eintragen; Datum der nächsten notieren.
\end{enumerate}

\subsection*{Monat 3: Löschübung}
\begin{enumerate}
\item Stelle die Notfallausrüstung nach Tab. 9.1 zusammen.
\item Entfache ein Übungsfeuer in der Blechwanne (maximal zwei Handvoll Holz).
\item Übe die Notbeendigung fünf Schritte (Konzept 9.1) vollständig.
\item Stoppe die Zeit; Ziel: unter 60 Sekunden bis zur Kaltprobe.
\item Trage das Ergebnis in Vorlage A.6 ein (als Übung gekennzeichnet).
\end{enumerate}

\subsection*{Monat 4: Drei Aufbauformen}
\begin{enumerate}
\item Baue Pyramide, Stern und Kanal je einmal am festen Platz.
\item Protokolliere je Form: Anzündzeit bis Kipppunkt, Rauch, Wind.
\item Lösche jede Form vollständig mit Handkaltprobe.
\item Vergleiche die drei Zeilen in Vorlage A.2.
\item Wähle deine Standardform fürs Kochen und begründe in einem Satz.
\end{enumerate}

\subsection*{Monat 5: Ersatzbrennstoffe beziehungsweise Trockenstapel}
\begin{enumerate}
\item Stadt: Weiche Papier ein, presse Briketts, lege sie zum Trocknen (4 Wochen).
\item Land: Spalte den Heckenschnitt sofort und lege Stapel 1 an.
\item Datieren, beschriften, Klangprobe an zehn Scheiten.
\item Trage beide Aktionen in Vorlage A.1 ein.
\end{enumerate}

\subsection*{Monat 6: Nachbarschafts-Absprache}
\begin{enumerate}
\item Sprich mit drei Nachbarn: Feuerzeiten, Rufkette, Sammelplatz.
\item Fülle den Nachbar-Sicherheitsplan (Tab. 9.5) mit ihnen aus.
\item Prüfe gemeinsam Wege und Löschwasser-Quellen.
\item Hänge den Alarmplan (Vorlage A.8) sichtbar aus.
\end{enumerate}

\subsection*{Monat 7: Kochstelle bauen}
\begin{enumerate}
\item Baue die Kochstelle nach Tab. 5.1 für deine Ausgangslage.
\item Koche eine einfache Mahlzeit (Brei oder Suppe) vollständig.
\item Miss und notiere: Holz vor/nach, Dauer, Wassermenge.
\item Übe die Morgenzündung aus der Glutdose am Folgetag.
\end{enumerate}

\subsection*{Monat 8: Retorte fahren}
\begin{enumerate}
\item Prüfe Platz, Rohr, Fass nach Konzept 8.1.
\item Fahre eine kleine Retorte mit 5–10 kg trockenem Holz.
\item Beobachte die drei Phasen am Rohr (Dampf, Dämpfe, Flamme).
\item Öffne erst nach vollständiger Abkühlung; wiege die Ausbeute.
\item Trage alles in Vorlage A.5 ein.
\end{enumerate}

\subsection*{Monat 9: Lauge und Asche}
\begin{enumerate}
\item Siebe die angesammelte Asche, wiege sie wöchentlich.
\item Setze eine Lauge nach Konzept 8.2 an (Handschuhe, Beschriftung).
\item Wasche eine Probe-Wäsche in verdünnter Lauge.
\item Land: bringe Asche nach Nutzungsplan in den Garten.
\item Notiere Reaktionen von Haut und Stoff in Vorlage A.5.
\end{enumerate}

\subsection*{Monat 10: Wärmesteine und Nacht-Disziplin}
\begin{enumerate}
\item Wähle und prüfe sechs Steine nach Konzept 6.2.
\item Führe den Nachtabschluss (Tab. 5.3) sieben Tage in Folge.
\item Nutze die Steine drei Nächte; führe das Wärme-Etat (Tab. 6.3).
\item Vergleiche den Holzverbrauch mit der Woche davor.
\end{enumerate}

\subsection*{Monat 11: Kalte Nacht}
\begin{enumerate}
\item Wähle eine Nacht mit angekündigtem Frost.
\item Baue den Schlafplatz nach Kapitel 6 Vertiefung auf.
\item Verzichte bewusst auf Feuer im Schlafbereich (Pflicht ohnehin).
\item Notiere morgens: Temperatur, Zufriedenheit, Verbesserung.
\item Wiederhole bei Fehlern im Folgemonat.
\end{enumerate}

\subsection*{Monat 12: Feuerprobe und Jahresvergleich}
\begin{enumerate}
\item Führe alle 20 Fragen der Feuerprobe (Anhang E) vorzeigen.
\item Vergleiche Etat-Ist mit Etat-Plan (Vorlage A.4).
\item Plane das Folgejahr: Einschlag (Land) oder Kisten-Etat (Stadt).
\item Übergib dich selbst an den Folgebänd mit der Devise des Bandes.
\end{enumerate}

